import{_ as o,o as a,c as d,a5 as t}from"./chunks/framework.-jms6n7v.js";const f=JSON.parse('{"title":"Python 변경 기록","description":"Python 패키지 darudb의 변경 기록이며, 최신 기록이 위에 옵니다. 패키지마다 버전을 따로 매기고 기록도 따로 둡니다. 다른 언어 패키지의 기록은 사이드바에서 언어를 바꾸면 볼 수 있습니다. 변경 기록은 패키지와 함께 관리하며 영어로 작성하므로, 아래 항목은 원문 그대로입니다.","frontmatter":{"title":"Python 변경 기록","order":1,"editLink":false,"outline":[2,3],"prev":{"text":"상수","link":"/ko/types/python/constants"},"next":{"text":"다른 DB와 비교","link":"/ko/compare"}},"headers":[{"level":2,"title":"Python 패키지 darudb","slug":"python-패키지-darudb","link":"#python-패키지-darudb","children":[{"level":3,"title":"darudb vNext (2026--)","slug":"darudb-vnext-2026","link":"#darudb-vnext-2026","children":[{"level":4,"title":"Changed","slug":"changed","link":"#changed","children":[]},{"level":4,"title":"Fixed","slug":"fixed","link":"#fixed","children":[]}]},{"level":3,"title":"darudb v1.1.0 (2026-10-09)","slug":"darudb-v1-1-0-2026-10-09","link":"#darudb-v1-1-0-2026-10-09","children":[{"level":4,"title":"Breaking changes","slug":"breaking-changes","link":"#breaking-changes","children":[]},{"level":4,"title":"Added","slug":"added","link":"#added","children":[]},{"level":4,"title":"Changed","slug":"changed-1","link":"#changed-1","children":[]},{"level":4,"title":"Fixed","slug":"fixed-1","link":"#fixed-1","children":[]}]},{"level":3,"title":"darudb v1.0.0 (2026-10-07)","slug":"darudb-v1-0-0-2026-10-07","link":"#darudb-v1-0-0-2026-10-07","children":[{"level":4,"title":"Added","slug":"added-1","link":"#added-1","children":[]}]}]}],"relativePath":"ko/changelog/python.md","filePath":"ko/changelog/python.md","lastUpdated":null}'),n={name:"ko/changelog/python.md"};function i(c,e,s,r,l,h){return a(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="python-변경-기록" tabindex="-1">Python 변경 기록 <a class="header-anchor" href="#python-변경-기록" aria-label="Permalink to &quot;Python 변경 기록&quot;">​</a></h1><p>Python 패키지 <code>darudb</code>의 변경 기록이며, 최신 기록이 위에 옵니다. 패키지마다 버전을 따로 매기고 기록도 따로 둡니다. 다른 언어 패키지의 기록은 사이드바에서 언어를 바꾸면 볼 수 있습니다. 변경 기록은 패키지와 함께 관리하며 영어로 작성하므로, 아래 항목은 원문 그대로입니다.</p><h2 id="python-패키지-darudb" tabindex="-1">Python 패키지 <code>darudb</code> <a class="header-anchor" href="#python-패키지-darudb" aria-label="Permalink to &quot;Python 패키지 `darudb`&quot;">​</a></h2><h3 id="darudb-vnext-2026" tabindex="-1">darudb vNext (2026--) <a class="header-anchor" href="#darudb-vnext-2026" aria-label="Permalink to &quot;darudb vNext (2026--)&quot;">​</a></h3><h4 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>A sync commit on Linux, Android and the BSDs makes the file durable with <code>fdatasync</code> rather than <code>fsync</code>, which leaves out the file&#39;s times and still syncs its length with its data. A sync commit of one object takes a quarter less time for it on a GitHub-hosted Linux runner, 312 µs against 413. macOS, iOS and Windows sync as before.</li><li>A commit asks the file system for the file&#39;s length only when its record counts pages past both the published commit&#39;s and the last one the commit wrote, rather than at every commit. A deferred commit of one object takes 11% less time for it on a GitHub-hosted Linux runner, 22.3 µs against 25.1.</li></ul><h4 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h4><ul><li><code>insert_many</code> and <code>put_many</code> of an asynchronous collection raise <code>DaruError</code> with <code>INVALID_ARGUMENT</code> for a batch that is not iterable, as the synchronous ones do, rather than <code>TypeError</code>.</li><li><code>backup</code> and <code>backup_async</code> refuse a <code>password_hashing</code> cost out of range with <code>INVALID_ARGUMENT</code> before they write anything, as opening does, whether a password is given or not. With a password they failed with <code>INTERNAL</code>, and without one they ignored the cost.</li></ul><h3 id="darudb-v1-1-0-2026-10-09" tabindex="-1">darudb v1.1.0 (2026-10-09) <a class="header-anchor" href="#darudb-v1-1-0-2026-10-09" aria-label="Permalink to &quot;darudb v1.1.0 (2026-10-09)&quot;">​</a></h3><h4 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h4><ul><li>The file format is version 6, <code>FORMAT_VERSION</code>, which earlier releases cannot open. Opening a file of version 5 raises it to version 6 while no other process has it open, so a file this release has opened no longer opens with 1.0, in Python or in any other language&#39;s package. An application that may go back to an earlier release, or that shares its file with a program still on one, opens with <code>upgrade_format=False</code>, which also creates new files in version 5, and calls <code>upgrade_format</code> once nothing older opens the file.</li></ul><h4 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li>The <code>upgrade_format</code> parameter of <code>Database.open</code> and <code>open_async</code>, and <code>upgrade_format</code> and <code>upgrade_format_async</code>, which say whether opening raises a file of an older format version, and raise an open one.</li></ul><h4 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to &quot;Changed&quot;">​</a></h4><ul><li>An index whose entries for one value come in key order, as a non-unique index&#39;s do while the objects&#39; primary keys grow, fills its pages as it goes, where splitting a page in the middle left half of each empty, and so do the branches of every tree. A file of 400,000 sample objects with 14 indexes is 7% smaller for it. Keys in no particular order split pages evenly, as before.</li><li><code>compact</code> and <code>compact_async</code> first write again, full, every tree whose pages inserts left part empty, so that the file ends about as small as a backup&#39;s copy: the same file compacts to 119 MiB rather than 140 MiB.</li><li>File format 6 writes the lengths in a leaf&#39;s entries as varints rather than in five bytes. A file of 400,000 sample objects with 14 indexes takes 8% fewer pages, 126 MiB against 138, and compacts to 110 MiB against 119, with reads and writes as fast as before. A file raised from version 5 has only its header rewritten; its leaves take the new layout as writes change them, and <code>compact</code> rewrites the trees where that saves room.</li><li>The native module is built with its loops aligned to 64 bytes, so that where a hot loop lands no longer depends on the rest of the build: in a development build, the position of one loop alone made one-object deferred commits 15% slower. It is about 7% larger for it. The build for 64-bit Arm Windows is the exception, since the compiler cannot write that platform&#39;s unwind information for a function with padding inside it.</li></ul><h4 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h4><ul><li><code>compact</code> and <code>compact_async</code> no longer grow the file when a value in an overflow run near the file&#39;s end finds no run of free pages below to move into. The run stays where it is, and a round of moves that would grow the file is dropped.</li></ul><h3 id="darudb-v1-0-0-2026-10-07" tabindex="-1">darudb v1.0.0 (2026-10-07) <a class="header-anchor" href="#darudb-v1-0-0-2026-10-07" aria-label="Permalink to &quot;darudb v1.0.0 (2026-10-07)&quot;">​</a></h3><h4 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h4><ul><li><code>Database.open</code> opens or creates a database file, with a <code>Schema</code> of classes decorated with <code>@collection</code>, and the options <code>create</code>, <code>page_size</code>, <code>busy_timeout</code>, <code>cache_size</code>, <code>key</code>, <code>password</code> and <code>password_hashing</code>; a <code>key</code> and a <code>password</code> together are refused with <code>INVALID_ARGUMENT</code>, here and in <code>salvage</code> and <code>backup</code>. A file holding an older schema version is migrated in one write transaction, through the <code>Migration</code>s given for the versions in between, whose <code>run</code> functions read the old objects through <code>Migrating.previous</code>.</li><li><code>@collection</code> and <code>@embedded</code> make a class a frozen, keyword-only dataclass whose annotations are its fields&#39; types: <code>bool</code>, <code>int</code>, <code>float</code>, <code>str</code>, <code>bytes</code>, lists of those, embedded classes, and any of them <code>| None</code> for an optional field. <code>field</code> adds a default, an index, a unique index, a primary key, a link to another collection, or a stored name of its own. A collection without a primary key is numbered by the engine, through its field <code>id: int | None = None</code>. An object read is built without the class&#39;s <code>__init__</code>, so a class with <code>__slots__</code> is refused.</li><li><code>db.read()</code> and <code>db.write()</code> are context managers: a write commits when its block ends, deferred with <code>durability=&quot;deferred&quot;</code>, and aborts when it raises. <code>txn.collection(User)</code> gives a collection&#39;s objects as instances of the class: <code>get</code>, <code>find</code>, <code>find_one</code> and <code>count</code>, and in a write <code>insert</code>, <code>insert_many</code>, <code>put</code>, <code>put_many</code>, <code>update</code> and <code>delete</code>. Write transactions on one file do not nest: a second one in the same thread is refused with <code>INVALID_ARGUMENT</code>, and so are <code>sync</code>, <code>close</code>, <code>compact</code> and the key changes inside one, which would wait for it.</li><li>Queries built from <code>F</code>: <code>F.age &gt;= 18</code>, <code>F.address.city == &quot;Seoul&quot;</code> through embedded objects and links, <code>between</code>, <code>is_in</code>, <code>contains</code>, <code>startswith</code>, <code>endswith</code> and null tests, combined with <code>&amp;</code>, <code>|</code> and <code>~</code>, in a <code>Query</code> with <code>where</code>, <code>sort_by</code>, <code>offset</code> and <code>limit</code>. Text in the query language with <code>$0</code>, <code>$1</code> and on, and <code>Database.prepare</code> with <code>param(0)</code> in a built query, compile a query once and run it with parameters.</li><li><code>Database.sync</code>, <code>close</code>, <code>set_key</code>, <code>set_password</code>, <code>is_encrypted</code>, <code>page_size</code>, <code>format_version</code> and <code>schema_version</code>. Every failure is a <code>DaruError</code> with the engine&#39;s error code.</li><li>The asynchronous API for <code>asyncio</code>: <code>Database.open_async</code>, <code>read_async</code>, <code>write_async</code>, <code>sync_async</code>, <code>close_async</code> and an <code>_async</code> twin of every tool and key change, which run the engine&#39;s work on a thread of the package&#39;s pool. The operations of one transaction run in the order they were called, and an event loop&#39;s asynchronous writes on one file take turns. A synchronous write, sync or close on the file from the event loop&#39;s thread while one runs, and an asynchronous one awaited inside it or in a task made inside it, are refused with <code>INVALID_ARGUMENT</code>. A migration&#39;s <code>run</code> may be a coroutine function with <code>open_async</code>.</li><li>The tools: <code>check</code>, the integrity check, which reports every problem in a <code>CheckReport</code>; <code>backup</code>, a copy of the published commit in a new file, under a new data key when it is given a <code>key</code> or a <code>password</code>; <code>compact</code>, which makes the file smaller in place; and <code>Database.salvage</code>, which rescues what it can of a damaged file into a new one.</li><li>The native module releases the GIL while the engine works, and declares itself safe for free-threaded Python.</li></ul>',20)])])}const p=o(n,[["render",i]]);export{f as __pageData,p as default};
